# 特征缩放：对 CSV 中选定的数值列逐列处理，未选列保持不变
import io
import pandas as pd

_method = {{method}}
_features = {{features}}
_min_value = float({{min_value}})
_max_value = float({{max_value}})
_q_low = float({{q_low}})
_q_high = float({{q_high}})

if data is None:
    raise RuntimeError('请先连接并运行上游的数据导入插件')

if isinstance(data, pd.DataFrame):
    _df = data.copy()
elif isinstance(data, bytes):
    _text = None
    for _encoding in ('utf-8-sig', 'utf-8', 'gbk', 'gb18030'):
        try:
            _text = data.decode(_encoding)
            break
        except UnicodeDecodeError:
            continue
    if _text is None:
        raise RuntimeError('CSV 编码无法识别')
    _df = pd.read_csv(io.StringIO(_text))
elif isinstance(data, str):
    _df = pd.read_csv(io.StringIO(data.lstrip('\ufeff')))
else:
    raise RuntimeError('输入 data 必须是 CSV 文本或 DataFrame')

if not isinstance(_features, (list, tuple)) or len(_features) == 0:
    raise RuntimeError('请至少选择一个需要缩放的列')

_missing = [str(_column) for _column in _features if _column not in _df.columns]
if _missing:
    raise RuntimeError('CSV 中找不到这些列：' + '、'.join(_missing))

if _method == 'Min-Max' and not _min_value < _max_value:
    raise RuntimeError('Min-Max 下限必须小于上限')
if _method == 'Robust' and not (0 <= _q_low < _q_high <= 100):
    raise RuntimeError('Robust 分位数必须满足 0 ≤ 下分位数 < 上分位数 ≤ 100')

for _column in _features:
    _original = _df[_column]
    _numeric = pd.to_numeric(_original, errors='coerce')
    _invalid = _original.notna() & _numeric.isna()
    if bool(_invalid.any()):
        _examples = _original[_invalid].astype(str).head(3).tolist()
        raise RuntimeError('列「' + str(_column) + '」包含非数值内容，例如：' + '、'.join(_examples))

    if _method == 'Z-score':
        _center = _numeric.mean()
        _scale = _numeric.std(ddof=0)
        _df[_column] = 0.0 if pd.isna(_scale) or _scale == 0 else (_numeric - _center) / _scale
    elif _method == 'Min-Max':
        _source_min = _numeric.min()
        _source_range = _numeric.max() - _source_min
        if pd.isna(_source_range) or _source_range == 0:
            _df[_column] = _min_value
        else:
            _df[_column] = (_numeric - _source_min) / _source_range * (_max_value - _min_value) + _min_value
    elif _method == 'Robust':
        _center = _numeric.median()
        _low = _numeric.quantile(_q_low / 100.0)
        _high = _numeric.quantile(_q_high / 100.0)
        _scale = _high - _low
        _df[_column] = 0.0 if pd.isna(_scale) or _scale == 0 else (_numeric - _center) / _scale
    elif _method == 'MaxAbs':
        _scale = _numeric.abs().max()
        _df[_column] = 0.0 if pd.isna(_scale) or _scale == 0 else _numeric / _scale
    else:
        raise RuntimeError('不支持的缩放方法：' + str(_method))

return _df.to_csv(index=False, lineterminator='\n')
